CREATE OR REPLACE EXTERNAL ACCESS INTEGRATION google_apis_access_integration
  ALLOWED_NETWORK_RULES = (google_apis_network_rule)
  ALLOWED_AUTHENTICATION_SECRETS = (oauth_token)
  ENABLED = true;

CREATE EXTERNAL ACCESS INTEGRATION my_integration
  ALLOWED_NETWORK_RULES = (my_rule, my_db.my_schema.my_other_rule)
  ALLOWED_API_AUTHENTICATION_INTEGRATIONS = (my_security_integration, my_other_integration)
  ALLOWED_AUTHENTICATION_SECRETS = all
  ENABLED = FALSE
  COMMENT = 'my integration';

CREATE EXTERNAL ACCESS INTEGRATION my_integration
  ALLOWED_NETWORK_RULES = (my_rule)
  ALLOWED_API_AUTHENTICATION_INTEGRATIONS = none
  ALLOWED_AUTHENTICATION_SECRETS = none
  ENABLED = TRUE;

ALTER EXTERNAL ACCESS INTEGRATION IF EXISTS dev_integration
  SET ALLOWED_AUTHENTICATION_SECRETS = (my_new_secret);

ALTER EXTERNAL ACCESS INTEGRATION IF EXISTS dev_integration_disabled
  SET ENABLED = FALSE;

ALTER EXTERNAL ACCESS INTEGRATION IF EXISTS dev_integration_disabled
  SET COMMENT = 'Disabled until the end of the Q1.';

ALTER EXTERNAL ACCESS INTEGRATION dev_integration SET
  ALLOWED_NETWORK_RULES = (rule_1, rule_2)
  ENABLED = TRUE
  TAG cost_center = 'finance', env = 'dev';

ALTER EXTERNAL ACCESS INTEGRATION dev_integration
  UNSET ALLOWED_API_AUTHENTICATION_INTEGRATIONS, ALLOWED_AUTHENTICATION_SECRETS, COMMENT, TAG cost_center;

ALTER EXTERNAL ACCESS INTEGRATION dev_integration UNSET ALLOWED_NETWORK_RULES;

DROP EXTERNAL ACCESS INTEGRATION dev_integration;

DROP EXTERNAL ACCESS INTEGRATION IF EXISTS dev_integration;

DROP CATALOG INTEGRATION IF EXISTS my_catalog_integration;

DESCRIBE EXTERNAL ACCESS INTEGRATION dev_integration;

DESC EXTERNAL ACCESS INTEGRATION dev_integration;

SHOW EXTERNAL ACCESS INTEGRATIONS;

SHOW EXTERNAL ACCESS INTEGRATIONS LIKE 'dev%';

-- The new keywords are not reserved.
SELECT allowed_network_rules, allowed_api_authentication_integrations FROM my_table;
